#!/usr/bin/env bash
# ORACLE-SITEMAP — R1 (site-set non-erosion). A CHECKER, not a printer.
# Reads oracles/expected-sites.txt (itself GENERATED by gen-expected-sites.sh) and compares it to the
# measured site set of <tree-root>. Reports MISSING (erosion) and UNEXPECTED (drift) and EXITS 1 on either.
# Phantom hits (the ordinary phrase 'ON TOP OF') are excluded and REPORTED, never silently dropped.
# Usage: ruleid-sitemap.sh <tree-root> [expected-sites.txt]
set -uo pipefail
D="$(cd "$(dirname "$0")" && pwd)"; . "$D/lib-corpus.sh"
R="${1:?tree root}"; EXP="${2:-$D/expected-sites.txt}"
[ -r "$EXP" ] || { echo "SITEMAP: FATAL expectation file unreadable: $EXP"; exit 2; }
rc=0
# PHANTOM LEDGER. Pass 3's first build claimed phantoms were "excluded and REPORTED" but the caller
# discarded measure()'s stderr with `2>/dev/null`, so the orchestrator's run produced ZERO such lines.
# The claim was false as shipped; the exclusions now land in a ledger that is always printed.
PH=$(mktemp); trap 'rm -f "$PH"' EXIT
measure(){ local id="$1"
  corpus_paths "$R" | while read -r f; do
    while IFS=: read -r ln _; do
      line=$(sed -n "${ln}p" "$f")
      if [ "$id" = TOP ] && printf '%s' "$line" | grep -q 'ON TOP OF' && ! printf '%s' "$line" | grep -qE '\(TOP\)|\*\*TOP\*\*'; then
        echo "PHANTOM-EXCLUDED $id ${f#$R/}:$ln [ON TOP OF]" >>"$PH"; continue; fi
      echo "${f#$R/}"
    done < <(grep -now -- "$id" "$f" 2>/dev/null)
  done | sort -u
}
while read -r id want; do
  case "$id" in ''|'#'*) continue ;; esac
  got=$(measure "$id")
  for w in $want; do grep -qx -- "$w" <<<"$got" || { echo "MISSING    $id $w"; rc=1; }; done
  while read -r g; do [ -z "$g" ] && continue
    grep -qw -- "$g" <<<"$want" || { echo "UNEXPECTED $id $g"; rc=1; }
  done <<<"$got"
done < "$EXP"
nph=$(sort -u "$PH" | wc -l)
echo "PHANTOM LEDGER: $nph excluded hit(s) — listed, never silently dropped:"
sort -u "$PH" | sed 's/^/  /'
[ "$nph" -eq 0 ] && echo "  (none — if this is 0 the exclusion path did not fire; that is a REPORT, not a pass)"
if [ $rc -eq 0 ]; then echo "SITEMAP: OK — every expected site present, no unexpected site (expectation: $(basename "$EXP"))"
else echo "SITEMAP: FAIL — site set eroded or drifted"; fi
exit $rc
